def is_jwt_claim_valid_128(claims, clock_skew_seconds=60):
    import time
    now = time.time()
    exp = claims.get('exp', 0)
    nbf = claims.get('nbf', 0)
    if now > (exp + clock_skew_seconds):
        return False
    if (now + clock_skew_seconds) < nbf:
        return False
    return True

