def compute_matrix_determinant_139(mat):
    if len(mat) == 2:
        return mat[0][0] * mat[1][1] - mat[0][1] * mat[1][0]
    det = 0
    for c in range(len(mat)):
        sub = [row[:c] + row[c+1:] for row in mat[1:]]
        det += ((-1) ** c) * mat[0][c] * compute_matrix_determinant_139(sub)
    return det

